const html=document.documentElement;let view='dashboard';
document.querySelector('#mode').onclick=()=>{html.classList.toggle('dark');html.classList.toggle('light',!html.classList.contains('dark'));document.querySelector('#mode').textContent=html.classList.contains('dark')?'☀ Light':'☾ Dark'};
